import { Suspense } from "react"

import { LiveRefresh } from "@/components/live-refresh"
import { UsbAttendanceProvider, UsbAttendanceReader } from "@/components/usb-attendance-reader"
import { parseMonitoringRange } from "@/features/attendance/live-monitoring"
import { MonitoringDateFilter } from "@/app/(portal)/admin/live-monitoring/components/monitoring-date-filter"
import { MonitoringPanelSkeleton } from "@/app/(portal)/admin/live-monitoring/components/monitoring-panel-skeleton"
import { MonitoringTable } from "@/app/(portal)/admin/live-monitoring/components/monitoring-table"
import { MonitoringUpdateProvider } from "@/app/(portal)/admin/live-monitoring/components/monitoring-update-provider"

export const dynamic = "force-dynamic"

async function SlowPanel({ from, to, delay, children }: { from: string; to: string; delay: number; children: React.ReactNode }) {
  await new Promise(resolve => setTimeout(resolve, delay))
  return <div><p>Panel {from} to {to}</p>{children}</div>
}

export default async function DebugLivePage({ searchParams }: { searchParams: Promise<{ from?: string; to?: string; delay?: string }> }) {
  const params = await searchParams
  const { from, to } = parseMonitoringRange(params)
  const delay = Number(params.delay ?? 300)

  return (
    <UsbAttendanceProvider>
      <div className="@container/main flex flex-1 flex-col gap-4 p-4 md:gap-6 md:p-6">
        <LiveRefresh channel="live-admin-monitoring" tables={["attendance_records", "students", "programs", "rfid_cards"]} debounceMs={300} />
        <div className="space-y-1">
          <h1 className="text-2xl font-semibold tracking-tight text-balance">Live Monitoring</h1>
        </div>
        <UsbAttendanceReader />
        <MonitoringUpdateProvider from={from} to={to}>
          <MonitoringDateFilter key={`${from}:${to}`} from={from} to={to} />
          <Suspense fallback={<MonitoringPanelSkeleton />}>
            <SlowPanel from={from} to={to} delay={delay}>
              <MonitoringTable rows={[]} />
            </SlowPanel>
          </Suspense>
        </MonitoringUpdateProvider>
      </div>
    </UsbAttendanceProvider>
  )
}
